#!/usr/bin/env bash
# recipes/crate-chrono--0-4-33/build.sh -- stage the chrono 0.4.33 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/chrono-0.4.33"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"9f13690e35a5e4ace198e7beea2895d29f3a9cc55015fcebe6336bd2010af9eb"}\n' > "${dest}/.cargo-checksum.json"
